S(0x454b60, 'GUESS famB 0x454b60', 'fastcall', None, ret='eax', gen=_mk(0x454980), note='batch200022')
S(0x455660, 'GUESS famB 0x455660', 'fastcall', None, ret='eax', gen=_mk(0x455330), note='batch200022')
